def topological_sort(graph):
    visited = set()
    order = []
    # States: 0 = unvisited, 1 = visiting (in current recursion stack), 2 = visited (completed)
    state = {node: 0 for node in graph}

    def visit(node):
        if state[node] == 1:
            raise ValueError('cycle detected')
        if state[node] == 2:
            return
        state[node] = 1  # Mark as visiting
        for dependency in graph.get(node, []):
            # If dependency is not in graph keys, it's an external node; we should still process it
            if dependency not in state:
                state[dependency] = 0
            visit(dependency)
        state[node] = 2  # Mark as visited
        order.append(node)

    for node in graph:
        visit(node)

    # Also visit any nodes that are dependencies but not in graph keys
    for node in list(state.keys()):
        if state[node] == 0:
            visit(node)

    return order
```

