    assert solution.parse_csv_line('"hello"') == ["hello"]

def test_quoted_with_doubled_and_comma():
    assert solution.parse_csv_line('"a""b,c"') == ['a"b,c']

def test_trailing_comma():
    assert solution.parse_csv_line("a,b,") == ["a", "b", ""]

def test_no_commas_no_quotes():
    assert solution.parse_csv_line("hello") == ["hello"]

