def parse_csv_line(line):
    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            # Start of a quoted field
            i += 1  # skip opening quote
            field = []
            while i < n:
                if line[i] == '"':
                    # Check for doubled quote
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1  # skip closing quote
                        # Skip any remaining characters until comma or end
                        while i < n and line[i] == ' ':
                            i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
            fields.append(''.join(field))
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
        # Skip comma if not at end
