def parse_csv_line(line):
    fields = []
    current_field = []
    i = 0
    n = len(line)
    while i < n:
        char = line[i]
        if char == '"':
            # Check for doubled quote
            if i + 1 < n and line[i + 1] == '"':
                current_field.append('"')
                i += 2
            else:
                # Skip the opening quote, we collect until closing quote
                i += 1
                # Now collect until we find closing quote
                while i < n:
                    if line[i] == '"':
                        if i + 1 < n and line[i + 1] == '"':
                            current_field.append('"')
                            i += 2
                        else:
                            # Closing quote found
                            i += 1
                            break
                    else:
                        current_field.append(line[i])
                        i += 1
        elif char == ',':
            fields.append(''.join(current_field))
            current_field = []
            i += 1
        else:
            current_field.append(char)
            i += 1
    fields.append(''.join(current_field))
    return fields
```

