        """A token that is not expired and not revoked should be accepted."""
        mock_is_token_valid.return_value = True
        result = authorize("valid_token", 1000)
        self.assertTrue(result)

    @patch('session.is_token_valid')
    def test_expired_token_raises_error(self, mock_is_token_valid):
        """An expired token should raise PermissionError."""
        mock_is_token_valid.return_value = False
        with self.assertRaises(PermissionError):
            authorize("expired_token", 1500)

    @patch('session.is_token_valid')
    def test_revoked_token_raises_error(self, mock_is_token_valid):
        """A revoked token should raise PermissionError."""
        mock_is_token_valid.return_value = False
        with self.assertRaises(PermissionError):
            authorize("revoked_token", 500)

    @patch('session.is_token_valid')
    def test_valid_token_at_boundary(self, mock_is_token_valid):
        """A token exactly at expiry time should be considered valid if not yet expired."""
        mock_is_token_valid.return_value = True
        result = authorize("boundary_token", 1000)
        self.assertTrue(result)

