        assert False, "Expected RuntimeError to be raised"
    except RuntimeError as e:
        assert 'error occurred' in str(e)


def test_failure_raises_runtime_error_with_returncode():
    """Test that RuntimeError is raised when returncode is non-zero."""
    try:
        run_checked([sys.executable, '-c', 'import sys; sys.exit(42)'])
        assert False, "Expected RuntimeError to be raised"
    except RuntimeError as e:
        assert 'command failed' in str(e)


def test_no_shell_used():
    """Test that shell is not used by checking shell=True is not passed."""
