def is_balanced(s):
    stack = []
    closing_to_opening = {
        ')': '(',
        ']': '[',
        '}': '{'
    }
    for c in s:
        if c in closing_to_opening:
            if not stack:
                return False
            if stack[-1] == closing_to_opening[c]:
                stack.pop()
            else:
                return False
        elif c in closing_to_opening.values():
            stack.append(c)
    return len(stack) == 0
