    mapping = {')': '(', ']': '[', '}': '{'}
    for c in s:
        if c in mapping.values():
            stack.append(c)
        elif c in mapping.keys():
            if not stack:
                return False
            top = stack.pop()
            if top != mapping[c]:
                return False
    return len(stack) == 0
```

