from scale import letter_grade

def grade(score):
    if score > 100 or score < 0:
        raise ValueError("Score must be between 0 and 100")

    # Standard boundaries: 90+ A, 80+ B, 70+ C, 60+ D, else F
    # Exact boundary scores (e.g. 90, 80, 70, 60) should map to their respective grades
    # The bug was that exact boundary scores were reported one letter too low
    # For example, score 90 was returning 'B' instead of 'A'

    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'
