import unittest
from solution import clean_path


class TestCleanPath(unittest.TestCase):
    """Tests for clean_path(path) that collapses repeated '/' characters while preserving absolute/relative nature."""

    def test_simple_absolute(self):
        """Absolute path with no repeated slashes remains unchanged."""
        self.assertEqual(clean_path("/usr/bin"), "/usr/bin")

    def test_simple_relative(self):
        """Relative path with no repeated slashes remains unchanged."""
        self.assertEqual(clean_path("usr/bin"), "usr/bin")

    def test_collapsed_absolute(self):
        """Multiple consecutive slashes in an absolute path are collapsed to a single slash."""
        self.assertEqual(clean_path("//usr///bin"), "/usr/bin")

    def test_collapsed_relative(self):
        """Multiple consecutive slashes in a relative path are collapsed to a single slash."""
        self.assertEqual(clean_path("usr///bin"), "usr/bin")

    def test_leading_slashes_absolute(self):
        """Leading slashes in an absolute path are collapsed to a single slash."""
        self.assertEqual(clean_path("////home"), "/home")

